#unistudy-bubble-moznu3fw8isfmsa .ancient-paper { background:#fffef9; border:1px solid #e8e0d0; border-radius:8px; padding:20px; margin-bottom:24px; position:relative; }
#unistudy-bubble-moznu3fw8isfmsa .ancient-paper::before { content:''; position:absolute; left:0; top:0; bottom:0; width:4px; background:#8b4513; border-radius:8px 0 0 8px; }
#unistudy-bubble-moznu3fw8isfmsa .poem-title { font-size:1.6rem; font-weight:bold; color:#5c2c0c; margin-bottom:4px; text-align:center; letter-spacing:2px; }
#unistudy-bubble-moznu3fw8isfmsa .poem-author { text-align:center; font-size:0.95rem; color:#8b4513; margin-bottom:16px; }
#unistudy-bubble-moznu3fw8isfmsa .poem-text { font-size:1.25rem; line-height:2.2; text-align:center; color:#1a1a1a; margin-bottom:20px; background:rgba(139,69,19,0.04); padding:16px; border-radius:6px; }
#unistudy-bubble-moznu3fw8isfmsa .section-head { display:inline-block; background:#8b4513; color:#fff; padding:2px 12px; border-radius:4px; font-size:0.9rem; margin-bottom:8px; margin-top:12px; }
#unistudy-bubble-moznu3fw8isfmsa .word-grid { display:grid; grid-template-columns:85px 1fr; gap:6px; font-size:0.95rem; align-items:start; }
#unistudy-bubble-moznu3fw8isfmsa .word-term { font-weight:bold; color:#b22222; text-align:right; padding-right:8px; border-right:2px solid #d4c4b0; }
#unistudy-bubble-moznu3fw8isfmsa .point-list { margin:8px 0; padding-left:20px; }
#unistudy-bubble-moznu3fw8isfmsa .point-list li { margin-bottom:8px; }
#unistudy-bubble-moznu3fw8isfmsa .btn { background:#8b4513; color:#fff; border:none; padding:10px 20px; border-radius:20px; font-family:inherit; font-size:1rem; cursor:pointer; margin:4px; transition:opacity 0.2s; box-shadow:0 2px 6px rgba(0,0,0,0.15); }
#unistudy-bubble-moznu3fw8isfmsa .btn:hover { opacity:0.9; transform: translateY(-1px); }
